24	function summarizeTools(toolsUsed) {
25	  const counts = {};
26	  let successes = 0;
27	  for (const t of toolsUsed) {
28	    const base = (t.tool || 'unknown').split('__')[0];
29	    counts[base] = (counts[base] || 0) + 1;
30	    if (t.success) successes++;
31	  }
32	  const parts = Object.entries(counts)
33	    .sort((a, b) => b[1] - a[1])
34	    .map(([k, v]) => `${k}×${v}`)
35	    .join(', ');
36	  const rate = toolsUsed.length
37	    ? `${Math.round((successes / toolsUsed.length) * 100)}%`
38	    : 'n/a';
39	  return { summary: parts || 'none', rate, total: toolsUsed.length, successes };
40	}
