42	function buildHint(state) {
43	  const parts = [];
44	  if (state.git?.branch) parts.push(`branch=${state.git.branch}`);
45	  const files = (state.files_written || []).slice(-3);
46	  if (files.length) parts.push(`files=${files.map(f => path.basename(f)).join(',')}`);
47	  if (state.aversions?.length) parts.push(`aversion="${state.aversions.slice(-1)[0]}"`);
48	  return `/compact Preserve: ${parts.join(' | ')}`;
